{
  "name": "@visulima/find-ai-runner",
  "version": "1.0.2",
  "description": "Detect and invoke AI CLI tools (Claude, Gemini, Codex, Copilot, Cursor, Crush, Amp, Kimi, Qwen, OpenCode, Droid) installed on the system",
  "keywords": [
    "ai",
    "ai-cli",
    "ai-runner",
    "amp",
    "claude",
    "cli-detection",
    "codex",
    "copilot",
    "crush",
    "cursor",
    "droid",
    "gemini",
    "kimi",
    "opencode",
    "qwen",
    "visulima"
  ],
  "homepage": "https://visulima.com/packages/find-ai-runner",
  "bugs": "https://github.com/visulima/visulima/issues",
  "license": "MIT",
  "author": {
    "name": "Daniel Bannert",
    "email": "d.bannert@anolilab.de"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/visulima/visulima.git",
    "directory": "packages/tooling/find-ai-runner"
  },
  "funding": [
    {
      "type": "github",
      "url": "https://github.com/sponsors/prisis"
    },
    {
      "type": "consulting",
      "url": "https://anolilab.com/support"
    }
  ],
  "bin": {
    "find-ai-runner": "./dist/cli.js"
  },
  "files": [
    "dist/**",
    "README.md",
    "CHANGELOG.md",
    "LICENSE.md"
  ],
  "type": "module",
  "sideEffects": false,
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    },
    "./package.json": "./package.json"
  },
  "publishConfig": {
    "access": "public",
    "provenance": true
  },
  "engines": {
    "node": "^22.14.0 || >=24.10.0"
  }
}
